{{הור2|ספר חופת חתנים (ר' רפאל מילדולה): מרגניתא טבא די השכחת בבית גניזא שמלכ"א בר אורי"ן ובר אבהן בכתר שם טוב עולה רחימא דנפשאי בן לאותו צדיק הרב המופלא חסידא קדישא הרב המחבר ספר עדות ביהוסף על הש"ס כמוהר"ר יוסף בן סאמון זצוק"ל תפילה הגונה ונאים הדברים למי שאמרם כאשר עיניך תחזינה מישרים לומר האשה ביום כניסתה לחופה כי עת לחננה כי בא מועד הסליחה כמובא בפנים וזו תוארה:}}

אֱלֹהִים מוֹשִׁיב יְחִידִים בַּיְתָה.{{ממס|תהלים סח ז}}{{ש}}
וַיֹּאמֶר אֱלֹהִים, נַעֲשֶׂה אָדָם בְּצַלְמֵנוּ כִּדְמוּתֵנוּ.{{ממס|בראשית א כו}} וַיִּבְרָא אֱלֹהִים אֶת הָאָדָם בְּצַלְמוֹ, בְּצֶלֶם אֱלֹהִים בָּרָא אֹתוֹ.{{ממס|בראשית א כז|שם פסוק כז}} וַיִּבֶן יְיָ אֱלֹהִים אֶת הַצֵּלָע אֲשֶׁר לָקַח מִן הָאָדָם לְאִשָּׁה, וַיְבִאֶהָ אֶל הָאָדָם.{{ממס|בראשית ב כב|שם ב כב}} וַיְבָרֶךְ אֹתָם אֱלֹהִים, וַיֹּאמֶר לָהֶם אֱלֹהִים, פְּרוּ וּרְבוּ וּמִלְאוּ אֶת הָאָרֶץ.{{ממס|בראשית א כח|שם א כח}}

אַתָּה הוּא יְיָ אֱלֹהִים, הָאֵל הַגָּדוֹל, הַגִּבּוֹר וְהַנּוֹרָא, אַתָּה עָשִׂיתָ אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ, אַתָּה הוּא יוֹצֵר הָאָדָם, וְנָפַחְתָּ בּוֹ רוּחַ וּנְשָׁמָה, וּבָרָאתָ אִישׁ וְאִשָּׁה, וְרָשַׁמְתָּ בָהֶם שִׁמְךָ הַקָּדוֹשׁ, יוֹ"ד בָּאִ{{סי|י}}שׁ וְהֵ"א בָּאִשָּׁ{{סי|ה}}, לְמַעַן דַּעַת וּלְלַמֵּד אוֹתָם לֵאמֹר: זָכוּ – שְׁכִינָה שְׁרוּיָה בֵינֵיהֶם. לָכֵן אֲנִי הָאִשָּׁה הַנִּצֶּבֶת לְפָנֶיךָ הַיּוֹם יְיָ הָאֱלֹהִים, אֱלֹהִים קְדוֹשִׁים, הַמּוּכֶנֶת וּמְזֻמֶּנֶת בִּקְדֻשָּׁה וּבְטָהֳרָה כְּדָת מֹשֶׁה וְיִשְׂרָאֵל עֲבָדֶיךָ, לִכָּנֵס לְחֻפָּה עִם הֶחָתָן בַּעְלִי. הִנְנִי מַפֶּלֶת תְּפִלָּה וְתַחֲנוּנִים לִפְנֵי כִסֵּא כְבוֹדֶךָ בָּעֵת וּבָעוֹנָה הַזֹּאת שֶׁאַתָּה מוֹחֵל לִי וּלְבַעְלִי עַל כָּל עֲוֹנוֹתֵינוּ וְחַטֹּאתֵינוּ וְאַשְׁמוֹתֵינוּ, כַּכָּתוּב: מָצָא אִשָּׁה מָצָא טוֹב, וַיָּפֶק רָצוֹן מֵיְיָ.{{ממס|משלי יח כב}} וַעֲוֹנוֹתֵינוּ מִתְפַּקְּקִין עַל יְדֵי תְּשׁוּבָה וּמַעֲשִׂים טוֹבִים וְחֻפָּה.

{{הערה|א"ה זאת התפלה טוב לאומרה ג"כ ביום הקודם לטבילת מצוה כמובן מענינה. (ויקיעורך: כך נוסף במקור לפני הקטע דלהלן, וראה בהערה הבאה.)}}יְהִי רָצוֹן מִלְּפָנֶיךָ שֶׁתַּשְׁרֶה שְׁכִינָתְךָ בֵּינִי וּבֵין בַּעְלִי וּתְיַחֵד עָלֵינוּ שִׁמְךָ הַקָּדוֹשׁ {{סי|י}}וֹ"ד {{סי|הֵ}}"א, וְתַכְנִיס בְּלִבֵּנוּ רוּחַ טָהֳרָה וּקְדֻשָּׁה, וְתַרְחִיק מִמֶּנּוּ כָּל מַחֲשָׁבוֹת וְהִרְהוּרִים רָעִים, וְתִתֶּן לָנוּ נֶפֶשׁ זַכָּה וּבָרָה בֵּינִי וּבֵין בַּעְלִי, וְלֹא נִתֵּן עֵינֵינוּ אֲנַחְנוּ שְׁנֵינוּ בְּשׁוּם אָדָם בָּעוֹלָם, כִּי אִם עֵינַי בְּבַעְלִי וְעֵינֵי בַעְלִי בִּי, וְיִהְיֶה בְעֵינַי כְּאִלּוּ אֵין אָדָם טוֹב וְיָפֶה וּבַעַל חֵן בָּעוֹלָם כְּמוֹ בַעְלִי, כַּדָּבָר שֶׁנֶּאֱמַר: שִׁמְעִי בַת וּרְאִי וְהַטִּי אָזְנֵךְ וְשִׁכְחִי עַמֵּךְ וּבֵית אָבִיךְ.{{ממס|תהלים מה יא}} וְנֶאֱמַר: כִּי הוּא אֲדֹנַיִךְ וְהִשְׁתַּחֲוִי לוֹ.{{ממס|תהלים מה יב}} וְכֵן אֶהְיֶה בְּעֵינֵי בַעְלִי כְּאִלּוּ אֵין אִשָּׁה יָפָה וּבַעֲלַת חֵן וַהֲגוּנָה בָּעוֹלָם כְּמוֹתִי, וְיִהְיוּ כָּל מַחְשְׁבוֹתָיו בִּי וְלֹא בְּשׁוּם בְּרִיָּה אַחֶרֶת בָּעוֹלָם, כְּדָבָר שֶׁנֶּאֱמַר: יָפְיָפִיתָ מִבְּנֵי אָדָם הוּצַק חֵן בְּשִׂפְתוֹתֶיךָ.{{ממס|תהלים מה ג}} וְנֶאֱמַר: וְיִתְאָו הַמֶּלֶךְ יָפְיֵךְ.{{ממס|תהלים מה יב}} וְנֶאֱמַר: עַל כֵּן יַעֲזָב אִישׁ אֶת אָבִיו וְאֶת אִמּוֹ וְדָבַק בְּאִשְׁתּוֹ.{{ממס|בראשית ב כד}}

וִיהִי רָצוֹן מִלְּפָנֶיךָ יְיָ הָאֱלֹהִים, שֶׁיִּהְיֶה זִוּוּגֵנוּ עוֹלֶה יָפֶה; {{ש}}
זִוּוּג הָגוּן שֶׁל אַהֲבָה וְאַחֲוָה שָׁלוֹם וְרֵעוּת. {{ש}}
זִוּוּג כָּשֵׁר כְּדָת מֹשֶׁה וּ[כְדָת] יְהוּדִית. {{ש}}
זִוּוּג הָגוּן שֶׁל יִרְאַת שָׁמַיִם וְיִרְאַת חֵטְא. {{ש}}
זִוּוּג שֶׁל בָּנִים הֲגוּנִים, צַדִּיקִים וּתְמִימִים וִישָׁרִים. {{ש}}
זִוּוּג שֶׁל זֶרַע שֶׁל קַיָּמָא. {{ש}}
זִוּוּג שֶׁל בְּרָכָה, כַּדָּבָר שֶׁנֶּאֱמַר: יְיָ זְכָרָנוּ יְבָרֵךְ, יְבָרֵךְ אֶת בֵּית יִשְׂרָאֵל.{{ממס|תהלים קטו יב}}  {{ש}}
זִוּוּג שֶׁיְּקֻיַּם בִּי הַדָּבָר שֶׁנֶּאֱמַר: אֶשְׁתְּךָ כְּגֶפֶן פֹּרִיָּה בְּיַרְכְּתֵי בֵיתֶךָ, בָּנֶיךָ כִּשְׁתִלֵי זֵיתִים סָבִיב לְשֻׁלְחָנֶךָ.{{ממס|תהלים קכח ג}} {{ש}}
זִוּוּג שֶׁיִּהְיֶה שָׂמֵחַ בִּי בַּעְלִי יוֹתֵר מִכָּל הַטּוֹבוֹת שֶׁיֵּשׁ לוֹ בָּעוֹלָם, כַּדָּבָר שֶׁנֶּאֱמַר: בַּיִת וָהוֹן נַחֲלַת אָבוֹת, וּמֵיְיָ אִשָּׁה מַשְׂכָּלֶת.{{ממס|משלי יט יד}} {{ש}}
זִוּוּג שֶׁלֹּא יִהְיֶה בֵּינִי וּבֵין בַּעְלִי לְעוֹלָם, לֹא כַעַס וְלֹא רֹגֶז, לֹא קִנְאָה וְלֹא תַחֲרוּת, אֶלָּא אַהֲבָה, אַחֲוָה, שָׁלוֹם וְרֵעוּת, וַעֲנָוָה וְרוּחַ נְמוּכָה וְסַבְלָנוּת. {{ש}}
זִוּוּג שֶׁל אַהֲבַת צְדָקָה וּגְמִילוּת חֲסָדִים וַעֲשִׂיַּת טוֹבָה לַבְּרִיּוֹת. {{ש}}
זִוּוּג שֶׁל זֶרַע שֶׁל קַיָּמָא בָּרִיא וָטוֹב, שֶׁלֹּא יִהְיֶה בּוֹ וְלֹא בְּשׁוּם אֶחָד מֵאֵבָרָיו שׁוּם נֶזֶק וְלֹא חִסָּרוֹן, לֹא פֶגַע וְלֹא נֶגַע, לֹא מַחֲלָה וְלֹא מַדְוֵה, לֹא כְאֵב וְלֹא צַעַר, לֹא רִפְיוֹן וְלֹא כִשָּׁלוֹן, וְלֹא יֶחְסַר טוֹב כָּל יְמֵי חַיָּיו. {{ש}}
זִוּוּג שֶׁתַּמְשִׁיךְ עָלֵינוּ בְּנִשְׁמָתֵנוּ וְרוּחֵנוּ וְנַפְשֵׁנוּ וְגוּפֵנוּ קְדֻשָּׁה וְטָהֳרָה, בְּמַחְשָׁבָה, בְּדִבּוּר וּבְמַעֲשֵׂה, כִּיהוּדִים כְּשֵׁרִים. {{ש}}
זִוּוּג כָּשֵׁר עַל דִּין יִשְׂרָאֵל קְדוֹשִׁים. {{ש}}
זִוּוּג שֶׁל הַצְלָחָה וּבְרָכָה – בִּרְכֹת שָׁמַיִם מֵעָל, בִּרְכֹת תְּהוֹם רֹבֶצֶת תָּחַת, בִּרְכֹת שָׁדַיִם וָרָחַם.{{ממס|בראשית מט כה}} {{ש}}
זִוּוּג שֶׁל זֶרַע קָדוֹשׁ וְטָהוֹר, טוֹב וְיָפֶה, מְתֻקָּן וּמְקֻבָּל.

וּבְכֵן{{הערה|במקור נוסף כאן: לְשֵׁם יִחוּד קֻדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵהּ בִּדְחִילוּ וּרְחִימוּ וּרְחִימוּ וּדְחִילוּ לְיַחֲדָא שֵׁם יו"ד ה"א בשם וא"ו ה"א, הֲרֵינִי מוּכֶנֶת וּמְזֻמֶּנֶת לַעֲשׂוֹת טְבִילָה כְּדָת מֹשֶׁה וְיִשְׂרָאֵל.}} יְהִי רָצוֹן מִלְּפָנֶיךָ יְיָ אֱלֹהִים, שֶׁתְּטַהֲרֵנוּ וּתְקַדְּשֵׁנוּ בִּקְדֻשָּׁתֶךָ, וְתַשְׁפִּיעַ עָלֵינוּ רוּחַ טָהֳרָה וּקְדֻשָּׁה מֵאִתְּךָ, וְתִתְרַצֶּה בָּנוּ וּבְמַעֲשֵׂנוּ, וּתְזַכֵּנוּ לַעֲשׂוֹת רְצוֹנְךָ תָּמִיד כָּל יְמֵי חַיֵּינוּ, וּתְבָרֵךְ אוֹתָנוּ מִבִּרְכוֹתֶיךָ, כִּי אַתָּה הוּא מְקוֹר הַבְּרָכוֹת בָּרוּךְ וּמְבֹרָךְ תָּמִיד.{{ש}}
בָּרוּךְ יְיָ לְעוֹלָם אָמֵן וְאָמֵן׃{{ממס|תהלים פט נג}}

{{הור|א"ה זאת התפלה ג"כ נראה שטוב לאומרה תדיר.}}{{ש}}
יְהִי רָצוֹן מִלְּפָנֶיךָ יְיָ אֱלֹהַי וֵאלֹהֵי אֲבוֹתַי אֱלֹהֵי אַבְרָהָם אֱלֹהֵי יִצְחָק וֵאלֹהֵי יַעֲקֹב שֶׁתִּשְׁמֹר וְתִנְצֹר וְתִנְטֹר תָּמִיד אֶת בַּעְלִי מִכָּל נֶזֶק וּמִכָּל רָע וּמִכָּל חֹלִי וְתִתֵּן לוֹ חַיִּים טוֹבִים חַיִּים אֲרֻכִּים חַיִּים שֶׁל עֹשֶׁר וְכָבוֹד וַתִּתֶּן לָנוּ זֶרַע שֶׁל קַיָּמָא וּבָנִים הֲגוּנִים וְצַדִּיקִים וְתִטַּע בֵּינֵינוּ תָּמִיד אַהֲבָה וְאַחֲוָה שָׁלוֹם וְרֵעוּת וְתִקְבַּע אַהֲבָתִי בְּלֵב בַּעְלִי שֶׁלֹּא יַחְשֹׁב בְּשׁוּם אִשָּׁה בָּעוֹלָם זוּלָתִי וְתִטַּע בְּלִבֵּנוּ אַהֲבָתְךָ וְיִרְאָתְךָ לַעֲשׂוֹת רְצוֹנְךָ וּלְעָבְדְּךָ בְּלֵבָב שָׁלֵם כִּיהוּדִים כְּשֵׁרִים וְלַעֲשׂוֹת צְדָקָה וָחֶסֶד עִם עַמְּךָ יִשְׂרָאֵל וּתְבָרֵךְ אֶת בַּעְלִי בְּרָכָה שְׁלֵמָה בְּרוֹב עֹז וְשָׁלוֹם כְּדָבָר שֶׁנֶּאֱמַר: יְבָרֶכְךָ יְיָ וְיִשְׁמְרֶךָ. יָאֵר יְיָ פָּנָיו אֵלֶיךָ וִיחֻנֶּךָּ. יִשָּׂא יְיָ פָּנָיו אֵלֶיךָ וְיָשֵׂם לְךָ שָׁלוֹם.{{ממס|במדבר ו#ו כד|במדבר ו כד-כו}} וְנֶאֱמַר: יְיָ יִשְׁמְרֵהוּ וִיחַיֵּהוּ וְאֻשַּׁר בָּאָרֶץ.{{ממס|תהלים מא ג}} אָמֵן וְכֵן יְהִי רָצוֹן.

